"""Tiny quiz-taking HTTP API."""
import random

from flask import Flask, jsonify, request

app = Flask(__name__)

# In-memory storage: quiz_id -> quiz dict
QUIZZES = {}
_NEXT_ID = [1]


class BadRequest(Exception):
    pass


def _require(cond, msg):
    if not cond:
        raise BadRequest(msg)


def _validate_quiz_payload(data):
    _require(isinstance(data, dict), "body must be a JSON object")
    _require(isinstance(data.get("title"), str) and data["title"].strip(),
             "'title' must be a non-empty string")
    questions = data.get("questions")
    _require(isinstance(questions, list) and len(questions) > 0,
             "'questions' must be a non-empty list")
    for i, q in enumerate(questions):
        _require(isinstance(q, dict), f"question {i} must be an object")
        _require(isinstance(q.get("text"), str) and q["text"].strip(),
                 f"question {i}: 'text' must be a non-empty string")
        choices = q.get("choices")
        _require(isinstance(choices, list) and len(choices) == 4
                 and all(isinstance(c, str) for c in choices),
                 f"question {i}: 'choices' must be a list of exactly 4 strings")
        ans = q.get("answer")
        _require(isinstance(ans, int) and not isinstance(ans, bool)
                 and 0 <= ans <= 3,
                 f"question {i}: 'answer' must be an integer in 0..3")


def _get_seed():
    raw = request.args.get("seed", "")
    try:
        return int(raw)
    except ValueError:
        raise BadRequest("'seed' query parameter must be an integer")


def _permutation(quiz_id, q_index, seed):
    """Deterministic choice permutation for one question."""
    rng = random.Random(f"{quiz_id}:{q_index}:{seed}")
    perm = list(range(len(QUIZZES[quiz_id]["questions"][q_index]["choices"])))
    rng.shuffle(perm)
    return perm


def _token(quiz_id, q_index, seed):
    """Opaque token encoding which presentation this question used."""
    return f"{quiz_id}.{q_index}.{seed}"


@app.errorhandler(BadRequest)
def handle_bad_request(e):
    return jsonify({"error": str(e)}), 400


@app.post("/quizzes")
def create_quiz():
    data = request.get_json(silent=True)
    if data is None:
        raise BadRequest("request body must be valid JSON")
    _validate_quiz_payload(data)
    quiz_id = str(_NEXT_ID[0])
    _NEXT_ID[0] += 1
    QUIZZES[quiz_id] = {
        "title": data["title"],
        "questions": [
            {"text": q["text"], "choices": list(q["choices"]), "answer": q["answer"]}
            for q in data["questions"]
        ],
    }
    return jsonify({"id": quiz_id}), 201


@app.get("/quizzes/<quiz_id>/take")
def take_quiz(quiz_id):
    quiz = QUIZZES.get(quiz_id)
    if quiz is None:
        return jsonify({"error": "quiz not found"}), 404
    seed = _get_seed()
    out = []
    for i, q in enumerate(quiz["questions"]):
        perm = _permutation(quiz_id, i, seed)
        out.append({
            "text": q["text"],
            "choices": [q["choices"][p] for p in perm],
            "token": _token(quiz_id, i, seed),
        })
    return jsonify({"id": quiz_id, "title": quiz["title"],
                    "seed": seed, "questions": out})


@app.post("/quizzes/<quiz_id>/attempts")
def submit_attempt(quiz_id):
    quiz = QUIZZES.get(quiz_id)
    if quiz is None:
        return jsonify({"error": "quiz not found"}), 404
    data = request.get_json(silent=True)
    if data is None:
        raise BadRequest("request body must be valid JSON")
    _require(isinstance(data, dict), "body must be a JSON object")
    seed = data.get("seed")
    _require(isinstance(seed, int) and not isinstance(seed, bool),
             "'seed' must be an integer")
    responses = data.get("responses")
    n = len(quiz["questions"])
    _require(isinstance(responses, list) and len(responses) == n,
             f"'responses' must be a list of {n} integers")
    correct = []
    for i, resp in enumerate(responses):
        _require(isinstance(resp, int) and not isinstance(resp, bool),
                 f"response {i} must be an integer")
        perm = _permutation(quiz_id, i, seed)
        _require(0 <= resp < len(perm), f"response {i} is out of range")
        # resp is an index into the *shuffled* choices; map back to original.
        correct.append(perm[resp] == quiz["questions"][i]["answer"])
    score = sum(correct) / n
    return jsonify({"score": score, "correct": correct})


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5001)

